import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"30、【离】 离下离上","description":"温公易说 - 30、【离】 离下离上","frontmatter":{"title":"30、【离】 离下离上","description":"温公易说 - 30、【离】 离下离上"},"headers":[],"relativePath":"zh/classics/wengong/031.md","filePath":"zh/classics/wengong/031.md"}'),n={name:"zh/classics/wengong/031.md"};function l(t,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_30、【离】-离下离上" tabindex="-1">30、【离】 离下离上 <a class="header-anchor" href="#_30、【离】-离下离上" aria-label="Permalink to “30、【离】 离下离上”">​</a></h1><h3 id="彖曰-离-丽也。日月丽乎天-百谷草木丽乎土。重明以丽乎正-乃化成天下。柔丽乎中正-故亨。是以畜牝牛吉也。" tabindex="-1">彖曰：离，丽也。日月丽乎天，百谷草木丽乎土。重明以丽乎正，乃化成天下。柔丽乎中正，故亨。是以畜牝牛吉也。 <a class="header-anchor" href="#彖曰-离-丽也。日月丽乎天-百谷草木丽乎土。重明以丽乎正-乃化成天下。柔丽乎中正-故亨。是以畜牝牛吉也。" aria-label="Permalink to “彖曰：离，丽也。日月丽乎天，百谷草木丽乎土。重明以丽乎正，乃化成天下。柔丽乎中正，故亨。是以畜牝牛吉也。”">​</a></h3><p>离利贞亨，离丽也。丽者，不可以不正也。夫明者，常失于察，察之甚者，或入于邪。是以圣人重明以丽乎正，乃能化成天下。柔者，失于弱而不立，故柔丽乎中正，然后乃亨。夫太明则察，太昧则蔽。二以明德而用中正，是以获元吉也。</p><h3 id="象曰-明两作离-大人以继明照于四方。" tabindex="-1">象曰：明两作离，大人以继明照于四方。 <a class="header-anchor" href="#象曰-明两作离-大人以继明照于四方。" aria-label="Permalink to “象曰：明两作离，大人以继明照于四方。”">​</a></h3><h3 id="初九-履错然-敬之-无咎-象曰-履错之敬-以辟咎也。" tabindex="-1">初九：履错然，敬之，无咎 象曰：履错之敬，以辟咎也。 <a class="header-anchor" href="#初九-履错然-敬之-无咎-象曰-履错之敬-以辟咎也。" aria-label="Permalink to “初九：履错然，敬之，无咎 象曰：履错之敬，以辟咎也。”">​</a></h3><p>初九敬之无咎何？夫火者，始于焰，焰而至于不可扑灭者也。是以明者虑于未兆，见于未萌，方事之初而错然矜慎，以避其咎也。</p><h3 id="六二-黄离-元吉-象曰-黄离元吉-得中道也。" tabindex="-1">六二：黄离，元吉 象曰：黄离元吉，得中道也。 <a class="header-anchor" href="#六二-黄离-元吉-象曰-黄离元吉-得中道也。" aria-label="Permalink to “六二：黄离，元吉 象曰：黄离元吉，得中道也。”">​</a></h3><h3 id="九三-日昃之离-不鼓缶而歌-则大耋之嗟-凶-象曰-日昃之离-何可久也" tabindex="-1">九三：日昃之离，不鼓缶而歌，则大耋之嗟，凶 象曰：日昃之离，何可久也？ <a class="header-anchor" href="#九三-日昃之离-不鼓缶而歌-则大耋之嗟-凶-象曰-日昃之离-何可久也" aria-label="Permalink to “九三：日昃之离，不鼓缶而歌，则大耋之嗟，凶 象曰：日昃之离，何可久也？”">​</a></h3><h3 id="九四-突如其来如-焚如-死如-弃如-象曰-突如其来如-无所容也。" tabindex="-1">九四：突如其来如，焚如，死如，弃如 象曰：突如其来如，无所容也。 <a class="header-anchor" href="#九四-突如其来如-焚如-死如-弃如-象曰-突如其来如-无所容也。" aria-label="Permalink to “九四：突如其来如，焚如，死如，弃如 象曰：突如其来如，无所容也。”">​</a></h3><p>突者，子之不顺者也。火性炎上，而九四以刚乘刚，用其不正以陵于上。若火之方炽，其来甚盛，极盛必衰，故死如弃如也。死者，祸之极也。弃者，众所不与也。</p><h3 id="六五-出涕沱若-戚嗟若-吉-象曰-六五之吉-离王公也。" tabindex="-1">六五：出涕沱若，戚嗟若，吉 象曰：六五之吉，离王公也。 <a class="header-anchor" href="#六五-出涕沱若-戚嗟若-吉-象曰-六五之吉-离王公也。" aria-label="Permalink to “六五：出涕沱若，戚嗟若，吉 象曰：六五之吉，离王公也。”">​</a></h3><h3 id="上九-王用出征-有嘉折首-获匪其丑-无咎-象曰-王用出征-以正邦也。" tabindex="-1">上九：王用出征，有嘉折首，获匪其丑，无咎 象曰：王用出征，以正邦也。 <a class="header-anchor" href="#上九-王用出征-有嘉折首-获匪其丑-无咎-象曰-王用出征-以正邦也。" aria-label="Permalink to “上九：王用出征，有嘉折首，获匪其丑，无咎 象曰：王用出征，以正邦也。”">​</a></h3>',12)])])}const f=e(n,[["render",l]]);export{b as __pageData,f as default};
